function ageFromBirthDate(value,today=new Date()){
  const match=String(value||"").match(/^(\d{4})-(\d{2})-(\d{2})$/);if(!match)return null;
  const year=Number(match[1]),month=Number(match[2]),day=Number(match[3]),birth=new Date(Date.UTC(year,month-1,day));
  if(birth.getUTCFullYear()!==year||birth.getUTCMonth()!==month-1||birth.getUTCDate()!==day)return null;
  const now=today instanceof Date?today:new Date(),todayDay=Date.UTC(now.getUTCFullYear(),now.getUTCMonth(),now.getUTCDate());if(birth.getTime()>todayDay)return null;
  let age=now.getUTCFullYear()-year;if(now.getUTCMonth()<month-1||(now.getUTCMonth()===month-1&&now.getUTCDate()<day))age--;
  return age>=0&&age<=130?age:null
}
